package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Flags a soft duplicate: an owner that passed the hard-duplicate check (see
 * {@link RequireUniqueIdentity}) but still looks like it may duplicate an existing one because
 * it shares that owner's lastName (compared case-insensitively) and postcode while giving a
 * different telephone. Sets {@link Owner#getPossibleDuplicate() possibleDuplicate} true and
 * {@link Owner#getPossibleDuplicateOf() possibleDuplicateOf} to the matching owner's id;
 * otherwise leaves the flag false and no reference.
 *
 * <p>Runs before {@link SaveOwner} so it compares only against already-stored owners and never
 * itself. When several owners match, the lowest id is chosen for a deterministic reference.
 */
public class FlagOwnerPossibleDuplicate {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        Integer matchId = null;
        if (owner.getPostcode() != null) {
            for (Owner existing : ownerRepository.findAll()) {
                if (sameName(existing.getLastName(), owner.getLastName())
                        && owner.getPostcode().equals(existing.getPostcode())
                        && !sameTelephone(existing.getTelephone(), owner.getTelephone())
                        && (matchId == null || existing.getId() < matchId)) {
                    matchId = existing.getId();
                }
            }
        }
        owner.setPossibleDuplicate(matchId != null);
        owner.setPossibleDuplicateOf(matchId);
    }

    private static boolean sameName(String a, String b) {
        return a == null ? b == null : a.equalsIgnoreCase(b);
    }

    private static boolean sameTelephone(String a, String b) {
        return a == null ? b == null : a.equals(b);
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Records how many owners the new owner's household holds once this owner is added: the
 * existing owners already assigned this owner's {@code householdId} by
 * {@link AssignOwnerHousehold} plus the new owner itself. An owner that does not share a
 * household ({@code householdId} is null) has a household size of 1.
 *
 * <p>Runs after {@link AssignOwnerHousehold} and before {@link SaveOwner}, so the count
 * reflects the household membership at creation time and never counts the new owner twice.
 */
public class AssignOwnerHouseholdSize {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        int count = 1; // the new owner, not yet saved
        String householdId = owner.getHouseholdId();
        if (householdId != null) {
            for (Owner existing : ownerRepository.findAll()) {
                if (householdId.equals(existing.getHouseholdId())) {
                    count++;
                }
            }
        }
        owner.setHouseholdSize(count);
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Shared owner identity for the create-owner pipeline: derives the single canonical
 * {@code identityKey} that consolidates all duplicate detection.
 *
 * <p>The key is {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId},
 * with telephone canonicalized to E.164 (see {@link OwnerTelephones}) and email lower-cased
 * (see {@link OwnerEmails}); a missing component contributes an empty string. Two owners are
 * duplicates exactly when their whole keys are equal — so members of the same household
 * (same {@code householdId}) with different telephones have different keys and are both
 * allowed.
 */
public final class OwnerIdentities {

    private OwnerIdentities() {
    }

    /**
     * Canonical identity key for the given components. {@code telephone} is normalized to
     * E.164 and {@code email} lower-cased before assembly; any {@code null} component
     * contributes an empty string.
     */
    public static String key(String telephone, String email, String householdId) {
        return part(OwnerTelephones.toE164(telephone)) + "|" + part(OwnerEmails.normalize(email))
                + "|" + part(householdId);
    }

    /** Canonical {@link #key(String, String, String)} for an existing owner's stored fields. */
    public static String of(Owner owner) {
        return key(owner.getTelephone(), owner.getEmail(), owner.getHouseholdId());
    }

    private static String part(String value) {
        return value == null ? "" : value;
    }
}

